INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Projektdokumentation immer für alle Projekte zwingend erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Projektgröße und Anforderungen"}, {"text": "Ja", "correct": false, "because": "Nicht immer vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel einer Projektdokumentation?', 3, '[{"text": "Nachvollziehbarkeit sichern", "correct": true, "because": "Dokumentiert Entscheidungen und Abläufe"}, {"text": "Maximale Länge", "correct": false, "because": "Klarheit wichtiger"}, {"text": "Manuelle Archivierung", "correct": false, "because": "Digital üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte gehören typischerweise in eine Projektdokumentation?', 5, '[{"text": "Projektziele", "correct": true, "because": "Definieren Erfolgskriterien"}, {"text": "Meilensteine", "correct": true, "because": "Zeigen Fortschritt"}, {"text": "Farbcodes", "correct": false, "because": "Irrelevant für Inhalt"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Dokumentationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Projektdokumentation dient der Transparenz. b) Sie ersetzt die Kommunikation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ergänzt, ersetzt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung einer Projektdokumentation?', 4, '[{"text": "Relevante Entscheidungen", "correct": false, "because": "Wichtig für Nachvollziehbarkeit"}, {"text": "Projektfortschritt", "correct": false, "because": "Zeigt Status"}, {"text": "Bildbearbeitung", "correct": true, "because": "Irrelevant für Dokumentation"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Projektdokumentation nur für interne Zwecke genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für externe Stakeholder relevant"}, {"text": "Ja", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für eine Projektdokumentation entscheidend?', 3, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Hohe Komplexität", "correct": false, "because": "Vermeidet Verständnis"}, {"text": "Manuelle Erstellung", "correct": false, "because": "Vorlagen effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Projektdokumentation?', 5, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Dokumentiert Abläufe"}, {"text": "Wissenstransfer", "correct": true, "because": "Hilft neuen Mitgliedern"}, {"text": "Maximale Länge", "correct": false, "because": "Kürze bevorzugt"}, {"text": "Grafische Animationen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Projektdokumentation unterstützt Audits. b) Sie ist nur für Programmierer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist für alle Stakeholder"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Projektdokumentation?', 4, '[{"text": "Projektziele", "correct": false, "because": "Definieren Zweck"}, {"text": "Zeitplan", "correct": false, "because": "Zeigt Ablauf"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Dokumentation"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Projektdokumentation nur für große Projekte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Projekte nützlich"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle Größen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen die Projektdokumentation?', 4, '[{"text": "Wikis", "correct": true, "because": "Fördern Kollaboration"}, {"text": "Dokumentenmanagement", "correct": true, "because": "Strukturiert Inhalte"}, {"text": "Videobearbeitung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Projektdokumentation immer veraltet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Aktuell bei Pflege"}, {"text": "Ja", "correct": false, "because": "Pflege hält aktuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erstellung einer Projektdokumentation?', 3, '[{"text": "Relevanz", "correct": true, "because": "Nur wichtige Informationen"}, {"text": "Maximale Details", "correct": false, "because": "Klarheit wichtiger"}, {"text": "Manuelle Eingaben", "correct": false, "because": "Vorlagen effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Projektdokumentation erleichtert Reviews. b) Sie ist nur für den Abschluss.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) begleitet ganzes Projekt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte verbessern eine Projektdokumentation?', 5, '[{"text": "Risikoanalysen", "correct": true, "because": "Zeigen Herausforderungen"}, {"text": "Lessons Learned", "correct": true, "because": "Fördern Verbesserung"}, {"text": "Unstrukturierte Notizen", "correct": false, "because": "Verwirren Leser"}, {"text": "Grafische Designs", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Projektdokumentation unwichtig?', 3, '[{"text": "Projektziele", "correct": false, "because": "Definiert Zweck"}, {"text": "Zeitplan", "correct": false, "because": "Zeigt Ablauf"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Dokumentationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Projektdokumentation für agile Projekte relevant ist?', 2, '[{"text": "Ja", "correct": true, "because": "Auch in Agilität nützlich"}, {"text": "Nein", "correct": false, "because": "Fördert Transparenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Soll eine Projektdokumentation komplex sein?', 3, '[{"text": "Nein", "correct": true, "because": "Klarheit und Kürze bevorzugt"}, {"text": "Ja", "correct": false, "because": "Komplexität verwirrt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer Projektdokumentation?', 4, '[{"text": "Erstellung eines IT-Projekts", "correct": true, "because": "Dokumentiert Abläufe und Ziele"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Projektarbeit"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
